mapper.select:
SELECT sc.sc_id as scId, sc.student_id as studentId, sc.course_id as courseId, sc.sc_score as score, sc.sc_selecttime as selectTime, u.user_real_name AS studentName, u.user_name AS studentNumber, s.student_class AS studentClass, c.course_name AS courseName
FROM student_course_table sc LEFT JOIN user_table u ON sc.student_id = u.user_id LEFT JOIN student_table s ON sc.student_id = s.user_id
LEFT JOIN course_table c ON sc.course_id = c.course_id WHERE sc.course_id = #{courseId}

mapper.update:
UPDATE student_course_table
SET sc_score = #{scScore},
    sc_updatetime = #{scUpdatetime}
WHERE student_id = #{studentId} AND course_id = #{courseId}
